  { name: 'Marketing digital SN', node: 'Alerte \u2014 Marketing digital S\u00e9n\u00e9gal' },
  { name: 'Digital marketing intl', node: 'Alerte \u2014 Digital marketing trends' },
  { name: 'Questions marketing', node: 'Alerte \u2014 Questions marketing digital Afrique' },
  { name: 'Google News Afrique', node: 'Google News RSS \u2014 Afrique' },
  { name: 'SEJ', node: 'RSS \u2014 Search Engine Journal' },
  { name: 'Moz', node: 'RSS \u2014 Moz Blog' },
  { name: 'SEO Afrique', node: 'Alerte \u2014 SEO Afrique francophone' },
  { name: 'Content marketing', node: 'Alerte \u2014 Content marketing Afrique' },
  { name: 'Email marketing', node: 'Alerte \u2014 Email marketing & automation' },
  { name: 'Monetisation blog', node: 'GNews \u2014 Blog mon\u00e9tisation Afrique' },
  { name: 'Copywriting', node: 'GNews \u2014 Copywriting r\u00e9daction web' },
  { name: 'Analytics', node: 'GNews \u2014 Google Analytics donn\u00e9es web' },
  { name: 'YT SEO FR', node: 'YouTube XML \u2014 SEO & Marketing FR' },
  { name: 'Product Hunt', node: 'RSS — Product Hunt (nouveaux outils)' },
  { name: 'Smashing Magazine', node: 'RSS — Smashing Magazine' },
  { name: 'The Verge AI', node: 'RSS — The Verge AI' },
  { name: 'IA image & gen', node: 'GNews — IA image & génération' },
  { name: 'Meta/IG updates', node: 'GNews — Meta / Instagram updates' },
  { name: 'TikTok updates', node: 'GNews — TikTok updates' },
  { name: 'LinkedIn updates', node: 'GNews — LinkedIn updates' },
  { name: 'Search Engine Land', node: 'RSS — Search Engine Land' },
  { name: 'CMI', node: 'RSS — Content Marketing Institute' },
  { name: 'Buffer', node: 'RSS — Buffer (social marketing)' },
  { name: 'Marketing AI Institute', node: 'RSS — Marketing AI Institute' },
  { name: 'The Rundown AI', node: 'RSS — The Rundown AI' },
];

for (const src of rssNodes) {
  try {
    const items = $(src.node).all();
    for (const item of items.slice(0, 5)) {
      const j = item.json;
      allSources.push({
        title: j.title || '', snippet: (j.contentSnippet || j.content || '').substring(0, 300),
        url: j.link || '', source: src.name
      });
    }
  } catch (e) {}
}

let messageQuestions = [];
try {
  const msgs = $('Firestore \u2014 Messages r\u00e9cents').first().json;
  messageQuestions = (msgs?.documents || []).slice(0, 10).map(doc => {
    const f = doc.fields || {};
    return { title: f.subject?.stringValue || '', snippet: (f.message?.stringValue || '').substring(0, 200), url: '', source: 'Messages visiteurs' };
  }).filter(m => m.title || m.snippet);
} catch(e) {}

let faqItems = [];
try {
  const faqs = $('Firestore \u2014 FAQ (questions fr\u00e9quentes)').first().json;
  faqItems = (faqs?.documents || []).map(doc => {
    const f = doc.fields || {};
    return { title: f.question?.stringValue || '', snippet: (f.answer?.stringValue || '').substring(0, 150), url: '', source: 'FAQ maxmorrys.me' };
  }).filter(f => f.title);
} catch(e) {}

return [{ json: {
  rss_results: allSources,
  user_questions: messageQuestions,
  faq_questions: faqItems,
  existing_articles: existingTitles,
  total_sources: allSources.length + messageQuestions.length + faqItems.length
} }];

const input = $input.first().json;
const today = new Date().toISOString().split('T')[0];

let parsed;
try {
  if (input.articles) { parsed = input; }
  else if (input.content?.parts) {
    parsed = JSON.parse(input.content.parts.map(p => p.text || '').join(''));
  } else { parsed = input; }
} catch (e) {
  throw new Error('Erreur parsing: ' + e.message);
}

const articles = (parsed.articles || []).map(a => ({
  Date: today, Titre_SEO: a.title_seo, Mot_Cle: a.main_keyword,
  Angle_Local: a.local_angle, Volume_Estime: a.competition_level,
  Score: a.seo_potential_score, Status: 'nouveau',
  Meta_Description: a.meta_description,
  Keywords_Secondaires: (a.secondary_keywords || []).join(', '),
  Structure: (a.suggested_structure || []).join(' | '),
  Longueur_Recommandee: a.recommended_length,
  Intent: a.search_intent, Content_Gap: a.content_gap,
  Inspiration: a.inspiration_source || ''
}));

return articles.map(a => ({ json: a }));
